import{_ as e,o as d,a,b as r}from"./app.UgfkfLuP.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"概览","link":"/api/SIMD-API/c_api/data_move_guide/overview/overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/overview/overview.md","filePath":"api/SIMD-API/c_api/data_move_guide/overview/overview.md","outlineHeaders":[{"level":2,"title":"接口分类","slug":"接口分类","link":"#接口分类"},{"level":2,"title":"硬件流水","slug":"硬件流水","link":"#硬件流水"},{"level":2,"title":"延伸阅读","slug":"延伸阅读","link":"#延伸阅读"}],"lastUpdated":1790563388000}'),o={name:"api/SIMD-API/c_api/data_move_guide/overview/overview.md"};function _(i,t,c,l,s,n){return d(),a("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>概览</h1><p>数据搬运是算子开发中最基础且最关键的操作之一。在AI Core的分层存储架构中，输入数据需要从Global Memory（GM）搬入片上存储，计算结果也需要从片上存储搬回GM；矩阵计算和矢量计算之间交换中间结果时，还会涉及L1 Buffer、L0 Buffer、Unified Buffer（UB）和寄存器之间的数据流转。</p><p>NPU架构版本3510的C API通过地址空间限定符和函数参数直接描述源、目的存储单元以及搬运形态。开发者需要根据数据通路选择接口，并显式配置地址、长度、步长、Padding、随路转换和流水同步。本章节用于在阅读各通路详解前，建立以下统一认知：</p><ul><li><strong>存储层级与数据通路：</strong> AI Core包含哪些物理存储单元，数据可沿哪些方向流动，以及各通路由哪条硬件流水执行。</li><li><strong>地址空间与执行范围：</strong> <code>__gm__</code>、<code>__cbuf__</code>、<code>__ca__</code>、<code>__cb__</code>、<code>__cc__</code>、<code>__ubuf__</code>等地址空间对应的物理存储，以及接口在AIC、AIV或Vector Function中的生效范围。</li><li><strong>搬运功能分类：</strong> 连续、高维切分、多维切片、随路格式转换、随路量化激活、非对齐、UB内部复制、矩阵分形搬运、NDDMA以及Reg与UB数据交换等能力。</li><li><strong>关键参数概念：</strong> <code>size</code>、<code>burst_count</code>、<code>burst_len</code>、<code>src_stride</code>、<code>dst_stride</code>、<code>src_gap</code>、<code>dst_gap</code>和多维循环参数的物理含义与单位差异。</li><li><strong>通用约束：</strong> 地址对齐、存储容量、有效访问范围、接口执行核、配置状态和同步规则。</li></ul><h2 id="接口分类">接口分类<a class="header-anchor" href="#接口分类">​</a></h2><table><thead><tr><th>分类</th><th>主要执行范围</th><th>典型通路</th><th>接口目录</th></tr></thead><tbody><tr><td>矢量数据搬运</td><td>AIV</td><td>GM与UB、UB到L1、UB内部</td><td><a href="../../vector_datamove/vector_datamove.html">矢量数据搬运</a></td></tr><tr><td>矩阵数据搬运</td><td>AIC</td><td>GM到L1、L1到L0A/L0B、L0C搬出、L1到专用Buffer</td><td><a href="../../cube_datamove/cube_datamove.html">矩阵计算搬运</a></td></tr><tr><td>Reg加载/存储</td><td>AIV的Vector Function</td><td>UB与矢量数据寄存器、掩码寄存器之间的数据交换</td><td><a href="../../reg_compute/load/reg_load_overview.html">Reg加载</a>、<a href="../../reg_compute/store/reg_store_overview.html">Reg存储</a></td></tr></tbody></table><h2 id="硬件流水">硬件流水<a class="header-anchor" href="#硬件流水">​</a></h2><table><thead><tr><th>流水</th><th>NPU架构版本3510中的主要搬运方向</th></tr></thead><tbody><tr><td>PIPE_MTE1</td><td>L1到L0A/L0B、L1到UB、L1到BiasTable</td></tr><tr><td>PIPE_MTE2</td><td>GM到L1、GM到UB</td></tr><tr><td>PIPE_MTE3</td><td>UB到GM、UB到L1</td></tr><tr><td>PIPE_FIX</td><td>L0C到GM/L1/UB、L1到Fixpipe Buffer</td></tr><tr><td>PIPE_V</td><td>UB内部复制和矢量计算</td></tr></tbody></table><p>同一流水中的指令按顺序执行，但后一条指令开始执行时，前一条指令不一定已完成全部数据读写；存在覆盖或读写依赖时，需要调用<a href="../../sync/intra_core_sync/asc_sync_pipe.html">asc_sync_pipe</a>等待前序指令完成。生产者和消费者位于不同流水时，需要根据数据依赖调用<a href="../../sync/system_sync_overview.html">同步控制</a>接口。接口所属流水、支持的执行核和同步方式以具体接口文档为准。</p><h2 id="延伸阅读">延伸阅读<a class="header-anchor" href="#延伸阅读">​</a></h2><ul><li><a href="data_move_concept.html">数据搬运概念</a>：理解不同搬运模式及其适用场景。</li><li><a href="data_path.html">数据通路</a>：按源、目的存储单元和硬件流水查找接口。</li><li><a href="overall_constraints.html">总体约束说明</a>：编码前检查对齐、容量、参数单位和同步要求。</li></ul></article></div>',1)])])}const v=e(o,[["render",_]]);export{p as __pageData,v as default};
